export const Task_TryLearningNextMove: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let result = MonTryLearningNewMove(gPlayerParty[gPartyMenu.slotId], false);

      switch (result)
      {
      case 0:  
          PartyMenuTryEvolution(taskId);
          break;
      case MON_HAS_MAX_MOVES:
          DisplayMonNeedsToReplaceMove(taskId);
          break;
      case MON_ALREADY_KNOWS_MOVE:
          return;
      default:
          DisplayMonLearnedMove(taskId, result);
          break;
      }
};

